import { Mesh, Group, PlaneGeometry, CircleGeometry, BoxGeometry, TorusGeometry, MeshStandardNodeMaterial, AmbientLight, DirectionalLight, PointLight, Color } from 'three/webgpu';
import { uniform, mix, vec3, uv as uvNode } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const cleanups = [];
  const root = new Group();
  group.add(root);

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const paper = new Color(colors.paper);
  const surface = new Color(colors.surface);
  const accent = new Color(colors.accent);

  // ---------------- Lighting: product-shot key + accent rim ----------------
  const ambient = new AmbientLight(0xffffff, 0.55);
  const keyLight = new DirectionalLight(0xfff4ec, 1.1);
  keyLight.position.set(2.2, 2.8, 3.0);
  const rimLight = new DirectionalLight(0xff2a38, 0.7);
  rimLight.position.set(-2.6, 1.2, -2.0);
  const fillLight = new PointLight(0xc8d2e4, 0.5, 18, 1.2);
  fillLight.position.set(0, -1.4, 2.2);
  root.add(ambient, keyLight, rimLight, fillLight);

  // ---------------- Backdrop plane (stage, never void): vertical gradient ----------------
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.depthWrite = false;
  const gradCol = mix(
    vec3(paper.r * 0.07, paper.g * 0.07, paper.b * 0.08),
    vec3(surface.r, surface.g, surface.b),
    uvNode.y
  );
  backdropMat.colorNode = gradCol;
  backdropMat.roughnessNode = uniform(0.9);
  backdropMat.metalnessNode = uniform(0.0);
  const backdrop = new Mesh(new PlaneGeometry(7.2, 6.0), backdropMat);
  backdrop.position.set(0, 0, -2.6);
  root.add(backdrop);

  // ---------------- Machined surface stat-tile card ----------------
  const cardGroup = new Group();
  root.add(cardGroup);

  const cardMat = new MeshStandardNodeMaterial();
  cardMat.colorNode = mix(vec3(0.09, 0.09, 0.12), vec3(0.18, 0.18, 0.24), uvNode.y.mul(0.5).add(0.4));
  cardMat.metalnessNode = uniform(0.55);
  cardMat.roughnessNode = mix(uniform(0.5), uniform(0.72), uvNode.y);
  cardMat.clearcoatNode = uniform(0.18);
  cardMat.envMapIntensityNode = uniform(1.0);

  const cardW = 1.9, cardH = 1.25, cardD = 0.12;
  const card = new Mesh(new BoxGeometry(cardW, cardH, cardD), cardMat);
  cardGroup.add(card);

  // Accent beveled edge ring on card face
  const edgeMat = new MeshStandardNodeMaterial();
  edgeMat.colorNode = mix(vec3(accent.r * 0.65, accent.g * 0.55, accent.b * 0.55), vec3(0.22, 0.2, 0.26), uvNode.x);
  edgeMat.metalnessNode = uniform(0.62);
  edgeMat.roughnessNode = uniform(0.42);
  const edge = new Mesh(new TorusGeometry(0.96, 0.022, 16, 4), edgeMat);
  edge.rotation.x = Math.PI / 2;
  edge.position.z = cardD / 2 + 0.014;
  edge.scale.set(cardW * 0.42, cardH * 0.42, 1);
  cardGroup.add(edge);

  // Contact shadow plane (grounded accent)
  const shadowMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
  });
  shadowMat.opacityNode = uniform(0.5);
  shadowMat.colorNode = vec3(0, 0, 0);
  const shadow = new Mesh(new CircleGeometry(0.85, 32), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.64, -0.1);
  root.add(shadow);

  // ---------------- Load GLB (sourced machined geometry) ----------------
  let glbRoot = null;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    glbRoot = gltf.scene;
    glbRoot.traverse((o) => {
      if (o.isMesh && (!o.material || !o.material.isNodeMaterial)) {
        const m = new MeshStandardNodeMaterial();
        m.colorNode = vec3(0.22, 0.22, 0.27);
        m.metalnessNode = uniform(0.7);
        m.roughnessNode = uniform(0.45);
        m.clearcoatNode = uniform(0.2);
        o.material = m;
      }
    });
    glbRoot.scale.set(0.32, 0.32, 0.32);
    glbRoot.position.set(0, 0, cardD / 2 + 0.02);
    root.add(glbRoot);
  }).catch(() => {});

  // ---------------- Entrance: weighted-settle + rise-in ----------------
  cardGroup.position.set(0, -0.4, 0);
  cardGroup.scale.set(0.96, 0.96, 0.96);
  (gsap.timeline())
    .to(cardGroup.position, { y: 0, duration: 0.7, ease: 'power3.out' })
    .to(cardGroup.position, { y: -0.01, duration: 0.5, ease: 'power4.out', yoyo: true, repeat: 1 }, '<+0.55')
    .to(cardGroup.scale, { x: 1.04, y: 1.04, z: 1.02, duration: 0.7, ease: 'power3.out' }, 0)
    .to(cardGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, '<+0.45');

  // ---------------- Cinematic primitives ----------------
  const primConfigs = config.cinematicPrimitives ?? [];
  const primHandles = [];
  for (const p of primConfigs) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      try {
        const res = fn(group, p.params ?? {});
        if (res) primHandles.push(res);
      } catch (e) {}
    }
  }

  // ---------------- Hover handler: rise-in subtle 0.15 units + tilt ----------------
  function onHoverEnter() {
    gsap.killTweensOf(cardGroup.position);
    gsap.killTweensOf(cardGroup.rotation);
    gsap.to(cardGroup.position, { y: 0.15, z: 0.08, duration: 0.4, ease: 'power2.out' });
    gsap.to(cardGroup.rotation, { x: -0.05, y: 0.05, duration: 0.3, ease: 'power2.out' });
  }
  function onHoverLeave() {
    gsap.killTweensOf(cardGroup.position);
    gsap.killTweensOf(cardGroup.rotation);
    gsap.to(cardGroup.position, { y: 0, z: 0, duration: 0.7, ease: 'power4.out' });
    gsap.to(cardGroup.rotation, { x: 0, y: 0, duration: 0.5, ease: 'power3.out' });
  }
  // ---------------- Click: press + emit ----------------
  function onClick() {
    gsap.killTweensOf(cardGroup.scale);
    gsap.to(cardGroup.scale, {
      x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.in',
      onComplete() {
        gsap.to(cardGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.4, ease: 'back.out(1.7)' });
      },
    });
    ctx.emit('hub-collection.select', {});
  }

  group.userData.handlers = {
    hover: [onHoverEnter, onHoverLeave],
    click: [onClick],
    pointerenter: [onHoverEnter],
    pointerleave: [onHoverLeave],
  };

  // ---------------- Cleanup ----------------
  group.userData.cleanup = () => {
    gsap.killTweensOf(cardGroup.position);
    gsap.killTweensOf(cardGroup.rotation);
    gsap.killTweensOf(cardGroup.scale);
    root.remove(ambient, keyLight, rimLight, fillLight, backdrop, shadow, cardGroup);
    cardGroup.remove(card, edge);
    card.geometry.dispose(); cardMat.dispose();
    edge.geometry.dispose(); edgeMat.dispose();
    backdrop.geometry.dispose(); backdropMat.dispose();
    shadow.geometry.dispose(); shadowMat.dispose();
    for (const h of primHandles) {
      try { h.timeline?.kill?.(); h.cleanup?.(); } catch (e) {}
    }
    if (glbRoot) {
      root.remove(glbRoot);
      glbRoot.traverse((o) => {
        if (o.isMesh) {
          o.geometry?.dispose?.();
          if (o.material?.dispose) o.material.dispose();
        }
      });
    }
  };

  return group;
}
